import orders from './orders.json' with { type: 'json' };

const ORDER_STATUS_SCHEMA = {
  type: 'object',
  properties: {
    order_id: {
      type: 'string',
      description: 'Identifier of the order to look up.'
    },
    include_history: {
      type: 'boolean',
      default: false,
      description: 'When true, include the chronological status history for the order.'
    }
  },
  required: ['order_id'],
  additionalProperties: false
};

const TOOLS = [
  {
    name: 'order_status',
    description: 'Look up the current status of an order, optionally including its chronological history.',
    inputSchema: ORDER_STATUS_SCHEMA
  }
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args = {}) {
  if (name !== 'order_status') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('arguments must be an object');
  }

  const allowed = new Set(['order_id', 'include_history']);
  const provided = Object.keys(args);
  const extras = provided.filter((k) => !allowed.has(k));
  if (extras.length > 0) {
    throw new Error(`Unexpected field(s): ${extras.join(', ')}`);
  }

  const { order_id, include_history } = args;

  if (typeof order_id !== 'string' || order_id.length === 0) {
    throw new Error('order_id must be a non-empty string');
  }

  let includeHistory = false;
  if (include_history !== undefined) {
    if (typeof include_history !== 'boolean') {
      throw new Error('include_history must be a boolean');
    }
    includeHistory = include_history;
  }

  const order = orders[order_id];
  if (!order) {
    throw new Error(`Order not found: ${order_id}`);
  }

  const lines = [`Order ${order_id}: status=${order.status}`];
  if (includeHistory) {
    lines.push(`History: ${order.history.join(' -> ')}`);
  }

  return { content: [{ type: 'text', text: lines.join('\n') }] };
}

